SELECT pg_temp.expect('10.3 chip rows (R000002 tapped No one does it well)', (SELECT count(*) FROM answer_item WHERE step_id = '10.3' AND attribute = 'chip' AND item_id = 'name' AND value_text = 'no one'), 1);
SELECT pg_temp.expect('answers whose latest answer_event differs from the answer', (
  SELECT count(*) FROM answer a
  JOIN LATERAL (SELECT e.revision, e.value_json FROM answer_event e WHERE e.submission_id = a.submission_id AND e.step_id = a.step_id
                ORDER BY e.revision DESC LIMIT 1) e ON true
  WHERE e.revision <> a.revision OR e.value_json IS DISTINCT FROM a.value_json), 0);

