-- 8. Rebuilding answer_item for a submitted run, as data-dictionary.md ("Rebuilding answer_item") describes, and
--    committed. The rows written back stand for flatten()'s output; verify.mjs runs the same rebuild with flatten().
BEGIN;
SELECT pg_temp.expect('rebuild: the run is locked', (SELECT count(*) FROM (SELECT 1 FROM submission WHERE submission_id = '8706edd2-b8c4-47bc-9464-db1eab7901fd' FOR UPDATE) x), 1);
LOCK TABLE answer_item IN EXCLUSIVE MODE;
ALTER TABLE answer_item DISABLE TRIGGER tg_answer_item_submitted;
CREATE TEMP TABLE rebuilt_rows ON COMMIT DROP AS SELECT submission_id, step_id, item_id, attribute, value_text, value_number, seq FROM answer_item WHERE submission_id = '8706edd2-b8c4-47bc-9464-db1eab7901fd';
DELETE FROM answer_item WHERE submission_id = '8706edd2-b8c4-47bc-9464-db1eab7901fd';
INSERT INTO answer_item (submission_id, step_id, item_id, attribute, value_text, value_number, seq) SELECT submission_id, step_id, item_id, attribute, value_text, value_number, seq FROM rebuilt_rows;
ALTER TABLE answer_item ENABLE TRIGGER tg_answer_item_submitted;
COMMIT;
SELECT pg_temp.expect('after the rebuild: R000002''s answer_item rows', (SELECT count(*) FROM answer_item WHERE submission_id = '8706edd2-b8c4-47bc-9464-db1eab7901fd'), 192);
SELECT pg_temp.expect_text('after the rebuild: tg_answer_item_submitted is enabled', (SELECT tgenabled::text FROM pg_trigger WHERE tgname = 'tg_answer_item_submitted'), 'O');
SELECT pg_temp.rejects('after the rebuild: a new answer_item row on the submitted run', 'INSERT INTO answer_item (submission_id, step_id, item_id, attribute, seq) VALUES (''8706edd2-b8c4-47bc-9464-db1eab7901fd'', ''1.1'', ''advice'', ''choice'', 2)');
-- a rebuild that fails part-way is undone whole: the rows and the trigger are as they were
DO $rebuild$
BEGIN
  BEGIN
    ALTER TABLE answer_item DISABLE TRIGGER tg_answer_item_submitted;
    DELETE FROM answer_item WHERE submission_id = '8706edd2-b8c4-47bc-9464-db1eab7901fd';
    INSERT INTO answer_item (submission_id, step_id, item_id, attribute, seq) VALUES ('8706edd2-b8c4-47bc-9464-db1eab7901fd', '1.1', 'advice', 'colour', 1);
    RAISE EXCEPTION 'CHECK FAILED: the broken rebuild was not refused';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
END $rebuild$;
SELECT pg_temp.expect('after a failed rebuild: R000002''s answer_item rows', (SELECT count(*) FROM answer_item WHERE submission_id = '8706edd2-b8c4-47bc-9464-db1eab7901fd'), 192);
SELECT pg_temp.expect_text('after a failed rebuild: tg_answer_item_submitted is enabled', (SELECT tgenabled::text FROM pg_trigger WHERE tgname = 'tg_answer_item_submitted'), 'O');

SELECT 'all checks passed';
